files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #15171c;
  --vt-ink: #181a1f;
  --vt-ink-soft: #6b6e76;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #111111;
  --vt-accent-ink: #111111;
  --vt-accent-on-deep: #c12828;
  --vt-line: rgba(24, 26, 31, 0.14);
  --vt-hero-gradient: linear-gradient(90deg, rgba(253, 187, 45, 0.72), rgba(34, 193, 195, 0.72));

  --vt-font-display: 'Anton', 'Arial Narrow', 'Arial', sans-serif;
  --vt-font-body: 'Inter', 'Arial', sans-serif;

  width: 100%;
  max-width: 100%;
  overflow-x: clip;
  font-family: var(--vt-font-body);
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.6;
}

.root,
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-family: var(--vt-font-display);
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: 0.01em;
}

.root :where(p) {
  margin: 0;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 3px solid var(--vt-accent-on-deep);
  outline-offset: 2px;
}

.sidebar {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  width: 280px;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 48px;
  padding: 48px 24px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.logo {
  display: inline-flex;
  color: var(--vt-on-accent);
}

.brand {
  font-size: 2rem;
  line-height: 1;
}

.navLinks {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.navLinks a {
  display: block;
  padding: 8px 18px;
  border-radius: 100px;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--vt-on-accent);
}

.navLinks a:hover {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
}

.main {
  margin-left: 280px;
  width: calc(100% - 280px);
  max-width: 100%;
}

.hero {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 665px;
  padding: 80px clamp(24px, 5vw, 70px);
  border-bottom: 15px solid var(--vt-accent);
  overflow: hidden;
}

.heroBg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-hero-gradient);
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 720px;
  color: var(--vt-ink);
}

.heroKicker {
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

.heroTitle {
  font-size: clamp(48px, 7vw, 84px);
  line-height: 0.95;
  text-transform: uppercase;
  margin-bottom: 18px;
}

.heroText {
  font-size: 1.15rem;
  max-width: 560px;
  margin-bottom: 28px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.buttonGhost,
.buttonSolid {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 100px;
  font-size: 0.85rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  border: 2px solid transparent;
}

.buttonGhost {
  border-color: var(--vt-ink);
  color: var(--vt-ink);
  background: transparent;
}

.buttonGhost:hover {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
}

.buttonSolid {
  background: var(--vt-accent-on-deep);
  border-color: var(--vt-accent-on-deep);
  color: var(--vt-on-deep);
}

.buttonSolid:hover {
  background: var(--vt-accent);
  border-color: var(--vt-accent);
  color: var(--vt-on-accent);
}

.section,
.sectionAlt {
  padding: 100px clamp(20px, 4vw, 50px);
}

.sectionAlt {
  background: var(--vt-surface-2);
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

.eyebrow {
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--vt-accent-on-deep);
  margin-bottom: 12px;
}

.title {
  font-size: clamp(36px, 4vw, 54px);
  text-transform: uppercase;
  margin-bottom: 40px;
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.storyMedia {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 16px;
  overflow: hidden;
}

.storyImage {
  width: 100%;
  height: 420px;
  object-fit: cover;
  border-radius: 20px;
  transform: rotate(4deg);
}

.storyBody {
  min-width: 0;
}

.storyText {
  display: grid;
  gap: 18px;
  color: var(--vt-ink-soft);
  font-size: 1.05rem;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
}

.card {
  background: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 20px;
  overflow: hidden;
  min-width: 0;
}

.cardMedia {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: var(--vt-surface-2);
}

.cardImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.card:hover .cardImage {
  transform: scale(1.04);
}

.pill {
  position: absolute;
  right: 16px;
  bottom: 16px;
  background: var(--vt-accent);
  border-radius: 10px;
  padding: 6px 14px;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--vt-on-accent);
}

.duration {
  position: absolute;
  left: 16px;
  bottom: 16px;
  background: var(--vt-surface-deep);
  border-radius: 10px;
  padding: 6px 12px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--vt-on-deep);
}

.cardBody {
  padding: 22px 24px 26px;
}

.cardTitle {
  font-size: 1.5rem;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.cardDesc {
  color: var(--vt-ink-soft);
  font-size: 0.98rem;
}

.priceGrid {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  gap: 64px;
  align-items: center;
}

.priceListBlock {
  min-width: 0;
}

.priceList {
  margin-top: 30px;
}

.priceRow {
  display: flex;
  align-items: baseline;
  gap: 0;
  padding: 14px 0;
  border-bottom: 1px solid var(--vt-line);
}

.priceName {
  font-family: var(--vt-font-display);
  font-size: 1.45rem;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.divider {
  flex: 1 1 auto;
  height: 2px;
  margin: 0 14px;
  background: repeating-linear-gradient(90deg, var(--vt-ink-soft) 0 4px, transparent 4px 8px);
  opacity: 0.45;
}

.priceValue {
  font-size: 1.25rem;
  color: var(--vt-accent-on-deep);
  white-space: nowrap;
}

.priceMedia {
  background: var(--vt-surface-deep);
  border-radius: 20px;
  padding: 12px;
  overflow: hidden;
}

.priceImage {
  width: 100%;
  height: 520px;
  object-fit: cover;
  border-radius: 20px;
  transform: rotate(3deg);
}

.contact {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.contact :where(h1, h2, h3, h4, h5, h6, p, span, a) {
  color: var(--vt-on-deep);
}

.contactHeader {
  padding: 90px 20px 0;
  text-align: center;
}

.titleLight {
  font-size: clamp(36px, 5vw, 54px);
  text-transform: uppercase;
  color: var(--vt-on-deep);
}

.contactGrid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: 48px;
  align-items: center;
  padding: 60px 0 20px;
}

.contactInfo {
  min-width: 0;
}

.contactHeading {
  font-size: 1.4rem;
  text-transform: uppercase;
  color: var(--vt-on-deep);
  margin-bottom: 18px;
}

.contactLine {
  margin-bottom: 8px;
  color: var(--vt-on-deep);
}

.contactLine a {
  color: var(--vt-on-deep);
  border-bottom: 1px solid currentColor;
  opacity: 0.85;
}

.contactLine a:hover {
  color: var(--vt-accent);
  opacity: 1;
}

.areas {
  margin-top: 16px;
  color: var(--vt-on-deep);
  opacity: 0.8;
}

.social {
  margin-top: 22px;
}

.hoursCard {
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 18px;
  min-height: 240px;
  overflow: hidden;
}

.hoursInner {
  width: 100%;
  background: var(--vt-accent-on-deep);
  border-radius: 20px;
  padding: 28px 20px;
  text-align: center;
  transform: rotate(5deg);
  color: var(--vt-on-deep);
}

.hoursTitle {
  font-size: 1.1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--vt-on-deep);
  margin-bottom: 10px;
}

.hoursText {
  color: var(--vt-on-deep);
  font-size: 1rem;
}

.footer {
  padding: 48px clamp(20px, 4vw, 50px) 80px;
  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  border-top: 1px solid var(--vt-line);
  border-bottom: 10px solid var(--vt-accent);
}

.footerTop {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 0.9rem;
}

.footerPostcode {
  margin-top: 8px;
  font-size: 0.85rem;
}

@media (max-width: 991px) {
  .sidebar {
    position: fixed;
    top: 0;
    right: 0;
    bottom: auto;
    left: 0;
    width: 100%;
    height: auto;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
  }

  .logo {
    margin: 0;
  }

  .brand {
    font-size: 1.4rem;
  }

  .navLinks {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 2px;
  }

  .navLinks a {
    padding: 6px 10px;
    font-size: 0.68rem;
    letter-spacing: 0.08em;
  }

  .main {
    margin-left: 0;
    width: 100%;
    padding-top: 70px;
  }

  .hero {
    min-height: 520px;
    padding: 70px 24px 60px;
  }

  .storyGrid,
  .priceGrid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .storyImage {
    height: 360px;
  }

  .priceImage {
    height: 360px;
  }

  .contactHeader {
    padding-top: 64px;
  }

  .contactGrid {
    grid-template-columns: 1fr;
    gap: 32px;
    padding-top: 40px;
  }
}

@media (max-width: 767px) {
  .section,
  .sectionAlt {
    padding: 60px 20px;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }

  .hero {
    min-height: 460px;
  }

  .heroTitle {
    font-size: 42px;
  }

  .heroActions {
    align-items: stretch;
  }

  .buttonGhost,
  .buttonSolid {
    text-align: center;
  }

  .contactGrid {
    padding-bottom: 40px;
  }

  .footer {
    padding-left: 20px;
    padding-right: 20px;
  }
}

@media (max-width: 480px) {
  .sidebar {
    padding: 8px 10px;
  }

  .brand {
    font-size: 1.1rem;
  }

  .navLinks a {
    padding: 5px 8px;
    font-size: 0.62rem;
  }

  .main {
    padding-top: 88px;
  }

  .hero {
    padding: 50px 18px;
    min-height: 420px;
  }

  .cardMedia {
    aspect-ratio: 4 / 3;
  }
}
